import numpy as np

def f(a):
    try:
        val1 = np.floor(22 * a)
        val2 = np.floor(22 * a * val1)
        val3 = np.floor(22 * a * val2)
        return a * val3
    except:
        return None

# Search for a in a reasonable range
# a > 0
solutions_pos = []
for i in np.linspace(0.001, 10, 1000000):
    if f(i) == 4:
        solutions_pos.append(i)

# a < 0
solutions_neg = []
for i in np.linspace(-10, -0.001, 1000000):
    if f(i) == 4:
        solutions_neg.append(i)

print("Pos:", solutions_pos)
print("Neg:", solutions_neg)

import math

def f(a):
    try:
        val1 = math.floor(22 * a)
        val2 = math.floor(22 * a * val1)
        val3 = math.floor(22 * a * val2)
        return a * val3
    except:
        return None

solutions = []
for C in range(-100000, 100001):
    if C == 0: continue
    a = 4 / C
    if f(a) == 4:
        solutions.append(a)

print(solutions)

